import SpecialFunctions: erfc
import JSON

"""
	gen( x, mu, c, name )

Generate fixture data and write to file.

The logarithm of the CDF is evaluated in extended precision from the textbook formula `ln(erfc(sqrt(c / (2*(x-mu)))))`, as `erfc` underflows in double precision close to `mu`.

# Arguments

* `x`: input value
* `mu`: location parameter
* `c`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = rand( 1000 ) .* 15;
julia> mu = rand( 1000 ) .* 10.0;
julia> c = rand( 1000 ) .* 5.0;
julia> gen( x, mu, c, "data.json" );
```
"""
function gen( x, mu, c, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( log.( erfc.( sqrt.( BigFloat.( c ) ./ ( 2 .* ( BigFloat.( x ) .- BigFloat.( mu ) ) ) ) ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("mu", mu),
		("c", c),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Negative mean:
mu = rand( 1000 ) .* -10.0;
x = rand( 1000 ) .* 15.0 .+ mu .+ 0.1;
c = ( rand( 1000 ) .* 5.0 ) .+ 1.0;
gen( x, mu, c, "negative_mean.json" );

# Positive mean:
mu = rand( 1000 ) .* 10.0;
x = rand( 1000 ) .* 15.0 .+ mu .+ 0.1;
c = ( rand( 1000 ) .* 5.0 ) .+ 1.0;
gen( x, mu, c, "positive_mean.json" );

# Large variance:
mu = rand( 1000 );
x = rand( 1000 ) .* 15.0 .+ mu .+ 0.1;
c = ( rand( 1000 ) .* 15.0 ) .+ 1.0;
gen( x, mu, c, "large_variance.json" );

# Close to `mu`:
mu = ( rand( 1000 ) .* 20.0 ) .- 10.0;
x = mu .+ exp10.( range( -15.0, stop = 0.0, length = 1000 ) );
c = ( rand( 1000 ) .* 5.0 ) .+ 0.1;
gen( x, mu, c, "near_mu.json" );
